                    !Array.isArray(q.mutexAmong) || q.mutexAmong.indexOf('pr_approved') === -1) {
                    return rule;
                }
                var patched = {};
                Object.keys(rule).forEach(function (k) { patched[k] = rule[k]; });
                patched.query = {};
