    });

    test('self-tick: dead gh CLI -> failure logged, run still succeeds', function () {
        var fx = fixture({ labels: ['pr_approved', 'ai_validated'], cliThrows: 'gh: command not found' });
        var result = fx.bot.action({ jobParams: { repo: 'a/b' } });
