        assert.equal(result.acted, 0);
        assert.ok(!result.log.some(function (l) { return l.indexOf('FIFO-queued') !== -1; }));
        assert.equal(fx.calls.cli.length, 0, 'no deferred approved was seen — no tick');
    });

