    test('self-tick: jobParams.selfTick=false disables the dispatch', function () {
        var fx = fixture({ labels: ['pr_approved', 'ai_validated'] });
        var result = fx.bot.action({ jobParams: { repo: 'a/b', selfTick: false } });
