        assert.equal(fx.wfCalls[0].workspace, 'a', 'active-SM probe is repo-scoped');
        assert.equal(fx.wfCalls[0].repository, 'b', 'active-SM probe is repo-scoped');
        assert.ok(result.log.some(function (l) {
