    if (msWant && (!item.pr || msWant.indexOf(item.pr.mergeState) === -1)) return false;
    // PR-carrier guards (issue #687 lifecycle rules): `checks` reads the
    // provider's check rollup (green/red/pending/none); `notMergeState`
