    var rvReal = function () {
        if (!rvReal.mod) rvReal.mod = loadModule('js/common/reviewVerdicts.js', makeRequire({}), {});
        return rvReal.mod;
    };
    var maReal = function () {
        if (!maReal.mod) maReal.mod = loadModule('js/common/machineAuthor.js', makeRequire({}), {});
        return maReal.mod;
