        }), {
            cli_execute_command: function () { return '{}'; }
        });
        return { agent: agent, holder: holder };
    }

    function providerWith(activeIssues, prStateByIssue, recorded) {
        return {
            activeMachineRuns: function () { return activeIssues; },
            listMachineIssues: function () {
                return [
