        var out = run(loaded.agent);

        assert.equal(out.idle, true, 'one live run at cap 1 still gates the tick');
        assert.deepEqual(out.waitingFor, [2001], 'the gate waits on the LIVE run only — the orphan is invisible');
    });
});

