        loaded.holder.provider = providerWith([2001], { 2001: 'OPEN' }, recorded);
        var out = run(loaded.agent);

        assert.equal(out.idle, true, 'the concurrency contract stands for live runs');
        assert.equal(out.waitingFor.join(','), '2001');
